INSERT INTO "perspectives" VALUES(1,'cosmological','Cosmological','The theme seen against the cosmos: sun, moon, planetary spheres, stars, and the cosmic origin of the human being.',0);
INSERT INTO "perspectives" VALUES(2,'evolutionary-historical','Evolutionary-historical','The theme traced through the evolution of earth and humanity: cultural epochs, history, changing consciousness.',1);
INSERT INTO "perspectives" VALUES(3,'physiological-medical','Physiological-medical','The theme as it lives in the human organism: the members of the human being, bodily processes, illness and healing.',2);
INSERT INTO "perspectives" VALUES(4,'christological','Christological','The theme in the light of the Christ Event, the Mystery of Golgotha and the Gospels.',3);
INSERT INTO "perspectives" VALUES(5,'artistic','Artistic','The theme approached through the arts: colour, music, speech, eurythmy, architecture, the experience of beauty.',4);
INSERT INTO "perspectives" VALUES(6,'social-practical','Social-practical','The theme applied to social and practical life: threefolding, economics, community, everyday tasks.',5);
INSERT INTO "perspectives" VALUES(7,'meditative-path','Meditative path','The theme as an inner path: exercises, meditation and the stages of higher knowledge.',6);
INSERT INTO "perspectives" VALUES(8,'pedagogical','Pedagogical','The theme from the standpoint of education and the development of the child.',7);
INSERT INTO "perspectives" VALUES(9,'natural-scientific','Natural-scientific','The theme related to natural science: Goethean observation, physics, chemistry, biology, agriculture.',8);
